{"function":"() => {
  const vw = window.innerWidth, vh = window.innerHeight;
  const out = { viewport: vw+'x'+vh };
  // find iframe with brew context
  const ifr = document.querySelector('iframe[data-context="brew"]');
  if (ifr) {
    const w = ifr.closest('.resizable');
    const wr = w.getBoundingClientRect();
    out.writingWindow = {
      rect: wr.width.toFixed(0)+'x'+wr.height.toFixed(0),
      left: wr.left.toFixed(0), top: wr.top.toFixed(0),
      inlineW: w.style.width, inlineH: w.style.height,
      iframeZoom: getComputedStyle(ifr).zoom,
      iframeW: ifr.getBoundingClientRect().width.toFixed(0),
    };
  }
  // measure other iframes for comparison
  out.otherContexts = {};
  document.querySelectorAll('iframe[data-context]').forEach(f => {
    out.otherContexts[f.dataset.context] = {
      zoom: getComputedStyle(f).zoom,
      rectW: f.getBoundingClientRect().width.toFixed(0),
    };
  });
  return out;
}"}

